@@ -65,6 +65,24 @@ List<String> frameContentLines(List<String> viewport) => [
   for (final line in viewport) line.trimRight(),
 ];

+/// One finished background shell job's settle notice (`[bash] sh-… exited(0)`)
+/// as painted into the raw stream by the CLI; exactly one per job proves the
+/// command started AND finished.
+final shellJobSettleNotice = RegExp(r'\[bash\] sh-(\S+) exited\(0\)');
+
+/// The DISTINCT settled shell-job numbers in [raw] — the start/finish proof
+/// set for background-job suites. Matched on the NUMBER PREFIX, never the
+/// full id: a frame repaint can interleave cursor-move escapes mid-id
+/// (observed under CI load: `sh-10-…xqo<esc>[11;29H5<esc>[11;31H exited(0)`),
+/// and a fragmented re-emit must not inflate the distinct-id set with a
+/// corrupt entry. The number is the first token written, so it survives any
+/// such fragmentation. Top-level (like [maskedValueRow]) so the settle
+/// predicate is unit-testable without a PTY.
+Set<String> settledJobNumbers(String raw) => shellJobSettleNotice
+    .allMatches(raw)
+    .map((m) => m.group(1)!.split('-').first)
+    .toSet();
+
 /// The shared deadline-poll engine behind [FaCliHarness.waitForText] and
 /// [FaCliHarness.waitForScreen]: polls [matched] every [pollInterval] until
 /// it turns true or [timeout] expires, then returns [onHit]() — waitForText
@@ -505,6 +523,31 @@ final class FaCliHarness {
     );
   }

+  /// Waits until [matched] accepts the accumulated raw output, then
+  /// returns that raw output (capture, don't re-read). The
+  /// predicate-anchored raw-stream wait: [waitForOutput] settles on
+  /// SILENCE — the wrong tool when the payload IS the stream, e.g.
+  /// waiting for N settle notices whose inter-arrival gaps rival the
+  /// settle window (gh-1337: the v1.0.520 countdown capture returned
+  /// mid-drain with the tail jobs unlanded because a stretched
+  /// inter-notice gap satisfied the silence rule). On expiry it throws
+  /// with the screen and raw-tail diagnostics — a settled-or-not answer
+  /// can never silently truncate the capture.
+  Future<String> waitForRaw(
+    bool Function(String raw) matched, {
+    String what = 'raw-output predicate',
+    Duration timeout = const Duration(seconds: 10),
+  }) {
+    return pollUntil(
+      matched: () => matched(_rawBuffer.toString()),
+      onHit: _rawBuffer.toString,
+      screenText: () => screenText,
+      rawTail: _rawTail,
+      what: what,
+      timeout: timeout,
+    );
+  }
+
   /// The last 2000 characters of raw output, for timeout diagnostics.
   String get rawTail => _rawTail();

diff --git a/test/integration/pty_harness_settled_jobs_test.dart b/test/integration/pty_harness_settled_jobs_test.dart
new file mode 100644
index 000000000..6b8db0733
--- /dev/null
+++ b/test/integration/pty_harness_settled_jobs_test.dart
@@ -0,0 +1,55 @@
+// Unit proof for the background-shell-job settle proof set
+// (`settledJobNumbers`, the drained-wait predicate behind the #573-review
+// countdown suite) — top-level and pure so the predicate is provable
+// without a PTY (same convention as `maskedValueRow` / `pollUntil`). Runs
+// in the DEFAULT suite (no integration tag).
+//
+// Regression (CI 2026-10-06, tag v1.0.520, PTY/CLI integration shard 2/3 —
+// issue #1337): the drained wait was a silence settle
+// (`waitForOutput(settleMs: 500)` returns on ~1 s of raw-stream quiet)
+// while the scenario staggers its ten sleeps exactly 1 s apart — a
+// stretched inter-notice gap satisfied the silence rule and returned the
+// capture mid-drain with only {1..7} settled. The wait now polls
+// `settledJobNumbers(raw).length == 10`, so the predicate itself is the
+// load-bearing logic pinned here.
+@TestOn('vm')
+library;
+
+import 'package:test/test.dart';
+
+import 'pty_harness.dart';
+
+void main() {
+  group('settledJobNumbers', () {
+    test('one distinct number per settle notice; repaint re-emits do not '
+        'inflate the set', () {
+      final raw = [
+        for (var i = 1; i <= 10; i++) '[bash] sh-$i-abc$i exited(0)',
+        // A frame repaint re-emits already-counted notices into the raw
+        // stream — the proof is the DISTINCT set, not the match count.
+        '[bash] sh-3-abc3 exited(0)',
+        '[bash] sh-10-abc10 exited(0)',
+      ].join('\n');
+
+      expect(settledJobNumbers(raw), {for (var i = 1; i <= 10; i++) '$i'});
+    });
+
+    test('a mid-id fragmentation (CI-load cursor escapes) still counts by '
+        'number prefix', () {
+      const raw = '[bash] sh-10-…xqo\x1b[11;29H5\x1b[11;31H exited(0)';
+      expect(settledJobNumbers(raw), {'10'});
+    });
+
+    test('the drained-wait predicate rejects a truncated capture (the '
+        'v1.0.520 {1..7} shape) and accepts only the full set', () {
+      String notices(int from, int to) => [
+        for (var i = from; i <= to; i++) '[bash] sh-$i-abc$i exited(0)',
+      ].join('\n');
+      bool settled(String raw) => settledJobNumbers(raw).length == 10;
+
+      expect(settled(notices(1, 7)), isFalse, reason: 'jobs 8-10 unlanded');
+      expect(settled(notices(1, 9)), isFalse, reason: 'job 10 unlanded');
+      expect(settled(notices(1, 10)), isTrue);
+    });
+  });
+}
