+
+      expect(settled(notices(1, 7)), isFalse, reason: 'jobs 8-10 unlanded');
+      expect(settled(notices(1, 9)), isFalse, reason: 'job 10 unlanded');
+      expect(settled(notices(1, 10)), isTrue);
+    });
+  });
